#!/bin/bash
# Apply the denniz changes to the MT6891-Mainline tree on a local branch "denniz" and commit them.
#  - embedded board DTB = mt6893-oneplus-denniz.dts (generated by mk-denniz-dts.py)
#  - head.S / log_store driver: second framebuffer candidate 0x77a20000 (chopin) -> 0x78810000 (denniz
#    mblock framebuffer region 0x78810000..0x7a600000); on denniz 0x77a20000 is ordinary RAM
#  - denniz_defconfig = chopin_defconfig minus DRM/SCP/sensorhub/BT/FB stripes, + server options, own cmdline
set -euo pipefail
N=/srv/nord2-pmos; K=$N/src/linux-mt6893; cd $K
git rev-parse --verify -q denniz >/dev/null || git checkout -q -b denniz
git config user.name >/dev/null || git config user.name "nord2-build"
git config user.email >/dev/null || git config user.email "nord2-build@localhost"
# i2c10..13 have no APDMA channel (vendor: "mediatek,fifo_only"): FIFO/PIO mode in i2c-mt65xx (MP2650 charger on i2c11)
python3 $N/repo/scripts/patch-i2c-fifo.py $K > /dev/null
# gen4m: station GTK in WTBL[BssIndex] (else the chip drops all WPA2 broadcast/multicast RX)
python3 $N/repo/scripts/patch-wifi-gtk-wtbl.py $K > /dev/null
python3 $N/repo/scripts/mk-denniz-dts.py arch/arm64/boot/dts/mediatek/mt6893-xiaomi-chopin.dts \
  $N/tests/twrp-hwinfo-20261114/live.dts arch/arm64/boot/dts/mediatek/mt6893-oneplus-denniz.dts
grep -q oneplus-denniz arch/arm64/boot/dts/mediatek/Makefile || \
  sed -i 's/^dtb-$(CONFIG_ARCH_MEDIATEK) += mt6893-xiaomi-chopin.dtb$/&\ndtb-$(CONFIG_ARCH_MEDIATEK) += mt6893-oneplus-denniz.dtb/' arch/arm64/boot/dts/mediatek/Makefile
grep -q oneplus-denniz arch/arm64/boot/dts/mediatek/Makefile
sed -i 's|#include "../boot/dts/mediatek/mt6893-xiaomi-chopin.dts"|#include "../boot/dts/mediatek/mt6893-oneplus-denniz.dts"|' arch/arm64/kernel/chopin-board.dts
grep -q oneplus-denniz arch/arm64/kernel/chopin-board.dts
sed -i 's/=0x77a20000/=0x78810000/; s/fb_band\t0x77a20000,/fb_band\t0x78810000,/' arch/arm64/kernel/head.S
! grep -q "^[^*]*0x77a20000" arch/arm64/kernel/head.S
sed -i 's/^#define FB_CAND1\t\t0x77a20000U/#define FB_CAND1\t\t0x78810000U\t\/* denniz *\//; s/^#define FB_REGION_SIZE\t\t0x27e0000U.*/#define FB_REGION_SIZE\t\t0x1df0000U\t\/* denniz mblock framebuffer region *\//' drivers/misc/mtk-logstore-console.c
grep -q "FB_CAND1.*0x78810000U" drivers/misc/mtk-logstore-console.c; grep -q "FB_REGION_SIZE.*0x1df0000U" drivers/misc/mtk-logstore-console.c
# Wi-Fi driver logging: user builds (BUILD_QA_DBG=0, also needed by conninfra) compile kalPrint/DBGLOG to nothing,
# so /proc/net/wlan/dbgLevel had no effect. DENNIZ_WLAN_LOG keeps the printing (not the ASSERTs); default
# level stays ERROR-only, raise per module with: echo 0xMM:0x3f > /proc/net/wlan/dbgLevel
W=drivers/misc/mediatek/connectivity/wlan_drv_gen4m
sed -i 's/^#if (BUILD_QA_DBG == 1)$/#if (BUILD_QA_DBG == 1) || defined(DENNIZ_WLAN_LOG)/' $W/os/linux/gl_kal.c $W/os/linux/include/gl_kal.h
[ "$(grep -c "defined(DENNIZ_WLAN_LOG)" $W/os/linux/gl_kal.c $W/os/linux/include/gl_kal.h | awk -F: '{s+=$2} END {print s}')" = 3 ]
grep -q DENNIZ_WLAN_LOG $W/Makefile || sed -i 's/^    ccflags-y += -DBUILD_QA_DBG=0$/&\n    ccflags-y += -DDENNIZ_WLAN_LOG/' $W/Makefile
grep -q "DDENNIZ_WLAN_LOG" $W/Makefile
# Wi-Fi TX hang: soc3_0 declares a third AP data ring (host WFDMA1 TX ring 2, "priority" frames: ARP, EAPOL,
# DHCP...), but on denniz its BASE/CNT registers read back as reset values (0 / 0x200) after init, so the
# first priority frame makes WFDMA1 fetch descriptors from address 0 and the whole TX/cmd/event side hangs
# (seen with devmem2: TX2 base=0 cidx=2, TX0 and cmd ring frozen). Route priority frames to ring 0 instead.
sed -i 's/^\t\.tx_ring2_data_idx = 2,$/\t.tx_ring2_data_idx = 0, \/* denniz: ring 2 never gets programmed *\//' $W/chips/soc3_0/soc3_0.c
grep -q "tx_ring2_data_idx = 0, /\* denniz" $W/chips/soc3_0/soc3_0.c
C=arch/arm64/configs/denniz_defconfig; cp arch/arm64/configs/chopin_defconfig $C
off() { for o in "$@"; do sed -i -E "/^(# )?CONFIG_$o[= ]/d" $C; echo "# CONFIG_$o is not set" >> $C; done; }
off DRM_MEDIATEK DRM_MEDIATEK_V2 DRM_PANEL_K10A_36_02_0A TOUCHSCREEN_NT36xxx_HOSTDL_SPI MTK_BOOT_PROGRESS_FB MTK_SCP_CHOPIN MTK_TINYSYS_SCP_SUPPORT MTK_SENSORHUB
# MTK_COMBO (CONNAC2 soc3_0 Wi-Fi + BT over BTIF) stays on: firmware + nvdata WIFI/BT_Addr come from scripts/wifi-fw.sh.
off RTC_SYSTOHC   # Android keeps the MT6359 RTC in its own encoding (mainline reads 2069): never write it from Linux
off USB_G_SERIAL   # legacy g_serial grabs the UDC before our configfs gadget (seen on the first boot)
sed -i -E '/^CONFIG_USB_CONFIGFS=/d; /^CONFIG_CONFIGFS_FS=/d' $C; echo CONFIG_USB_CONFIGFS=y >> $C; echo CONFIG_CONFIGFS_FS=y >> $C
# Server parity with the 9 Pro, all built in (no modules are shipped in the rootfs): nftables + NAT (iptables-nft
# via NFT_COMPAT; the legacy iptables tables need IP_NF_IPTABLES_LEGACY and are not wanted),
# Docker (bridge, veth, overlay, cgroups), policy routing + WireGuard (Tailscale), zram swap, btrfs/f2fs,
# USB Ethernet adapters (for when host mode works), /proc/config.gz.
on() { for o in "$@"; do sed -i -E "/^(# )?CONFIG_$o[= ]/d" $C; echo "CONFIG_$o=y" >> $C; done; }
on NETFILTER NETFILTER_ADVANCED NF_CONNTRACK NF_NAT NF_TABLES NF_TABLES_INET NF_TABLES_IPV4 NF_TABLES_IPV6 \
   NFT_CT NFT_NAT NFT_MASQ NFT_REJECT NFT_COMPAT NFT_LIMIT NFT_LOG NFT_FIB_INET NFT_FIB_IPV4 NFT_FIB_IPV6 \
   NETFILTER_XTABLES NETFILTER_XT_MATCH_CONNTRACK NETFILTER_XT_MATCH_ADDRTYPE NETFILTER_XT_MATCH_MULTIPORT \
   NETFILTER_XT_MATCH_COMMENT NETFILTER_XT_MARK NETFILTER_XT_NAT NETFILTER_XT_TARGET_MASQUERADE \
   IP_NF_IPTABLES IP6_NF_IPTABLES \
   BRIDGE BRIDGE_NETFILTER BRIDGE_VLAN_FILTERING VETH OVERLAY_FS MACVLAN IPVLAN VXLAN DUMMY \
   CGROUP_BPF CGROUP_HUGETLB CGROUP_PERF CGROUP_NET_PRIO CGROUP_NET_CLASSID NET_CLS_CGROUP CFS_BANDWIDTH \
   IP_MULTIPLE_TABLES IPV6_MULTIPLE_TABLES IP_ADVANCED_ROUTER WIREGUARD TUN \
   ZRAM ZSMALLOC ZRAM_BACKEND_LZ4 ZRAM_BACKEND_ZSTD CRYPTO_LZ4 CRYPTO_ZSTD I2C_CHARDEV BTRFS_FS BTRFS_FS_POSIX_ACL F2FS_FS \
   USB_USBNET USB_NET_CDCETHER USB_RTL8152 USB_NET_AX88179_178A IKCONFIG IKCONFIG_PROC \
   USB_UAS EXFAT_FS NTFS3_FS NLS_UTF8 \
   BT BT_BREDR BT_LE MTK_BTIF MTK_COMBO_BT \
   DRM_PANFROST COMMON_CLK_MT6893_PG BT_RFCOMM BT_RFCOMM_TTY BT_BNEP BT_HIDP \
   BLK_DEV_THROTTLING
# Display (work in progress, opt-in): mediatek_v2 stack + the denniz AMS643YE05 cmd-mode panel driver
if [ "${DENNIZ_DISPLAY:-0}" = 1 ]; then
  python3 $N/repo/scripts/patch-display.py $K $N/repo > /dev/null
  python3 $N/repo/scripts/patch-display-cputrig.py $K > /dev/null
  sed -i -E '/^(# )?CONFIG_(DRM_MEDIATEK|DRM_MEDIATEK_V2|DRM_PANEL_ONEPLUS_DENNIZ)[= ]/d' $C
  printf 'CONFIG_DRM_MEDIATEK=y\nCONFIG_DRM_MEDIATEK_V2=y\nCONFIG_DRM_PANEL_ONEPLUS_DENNIZ=y\n' >> $C
fi
sed -i -E '/^CONFIG_CMDLINE=/d' $C
echo 'CONFIG_CMDLINE="console=tty0 earlycon=mtk8250,mmio32,0x11002000 clk_ignore_unused regulator_ignore_unused pd_ignore_unused ignore_loglevel panic=5 printk.devkmsg=on log_buf_len=4194304 pstore.kmsg_bytes=262144 ramoops.mem_address=0x48090000 ramoops.mem_size=0x8f000 ramoops.record_size=0x1000 ramoops.console_size=0x40000 ramoops.ftrace_size=0 ramoops.pmsg_size=0 rdinit=/init"' >> $C
git add -A drivers/i2c/busses/i2c-mt65xx.c drivers/gpu/drm/panel drivers/gpu/drm/mediatek/mediatek_v2/mtk_drm_crtc.c $W/mgmt/privacy.c $W/chips/soc3_0/soc3_0.c $W/os/linux/gl_kal.c $W/os/linux/include/gl_kal.h $W/Makefile arch/arm64/boot/dts/mediatek/mt6893-oneplus-denniz.dts arch/arm64/boot/dts/mediatek/Makefile \
  arch/arm64/kernel/chopin-board.dts arch/arm64/kernel/head.S drivers/misc/mtk-logstore-console.c $C
git commit -q -m "denniz: OnePlus Nord 2 5G first-boot board tree and config" && git log --oneline -2
git diff HEAD~1 --stat
